select.where:
s.del_flag = '0'

	AND s.id = #{id}


	AND s.repair_order_id = #{repairOrderId}


	AND o.order_no = #{orderNo}


	AND s.status = #{status}


	AND c.unit_name like concat('%', #{customerName}, '%')


	AND a.repair_no = #{applyNo}


	and s.create_time >= #{params.beginTime}


	and s.create_time < DATE_ADD(DATE(#{params.endTime}), INTERVAL 1 DAY)
